  "answer": "```python\nimport asyncio\nfrom unittest import mock\n\nimport dspy\nfrom litellm.utils import Choices, Message, ModelResponse\n\n\nclass DummySendStream:\n    def __init__(self):\n        self.chunks = []\n\n    async def send(self, chunk):\n        self.chunks.append(chunk)\n\n\nasync def empty_async_generator():\n    if False:\n        yield None\n\n\nasync def main():\n    auth_header = {\"Authorization\": \"Bearer secret-token\"}\n    stream = DummySendStream()\n    final_response = ModelResponse(\n        choices=[Choices(message=Message(role=\"assistant\", content=\"streamed\"))],\n        usage={\"prompt_tokens\": 1, \"completion_tokens\": 1, \"total_tokens\": 2},\n        model=\"openai/gpt-4o-mini\",\n    )\n    fallback_response = ModelResponse(\n        choices=[Choices(message=Message(role=\"assistant\", content=\"non-stream\"))],\n        usage={\"prompt_tokens\": 1, \"completion_tokens\": 1, \"total_tokens\": 2},\n        model=\"openai/gpt-4o-mini\",\n    )\n\n    # First call: force the async streaming branch so DSPy routes through\n    # _get_stream_completion_fn, which adds stream_options when track_usage=True.\n    with (\n        mock.patch(\"litellm.acompletion\", return_value=empty_async_generator()) as streamed_acompletion,\n        mock.patch(\"litellm.stream_chunk_builder\", return_value=final_response),\n    ):\n        lm = dspy.LM(model=\"openai/gpt-4o-mini\", cache=False)\n        with dspy.context(send_stream=stream, track_usage=True, caller_predict=None):\n            streamed_result = await lm.acall(\"hello\", headers=auth_header)\n\n    streamed_kwargs = streamed_acompletion.call_args.kwargs\n    print(\"streamed_result:\", streamed_result)\n    print(\"streamed_call_kwargs:\", streamed_kwargs)\n\n    assert streamed_result == [\"streamed\"]\n    assert streamed_kwargs[\"stream\"] is True\n    assert streamed_kwargs[\"stream_options\"] == {\"include_usage\": True}\n    assert streamed_kwargs[\"headers\"] is None\n\n    # Second call: remove send_stream so alitellm_completion takes its normal\n    # async fallback and forwards headers through _add_dspy_identifier_to_headers.\n    with mock.patch(\"litellm.acompletion\", return_value=fallback_response) as fallback_acompletion:\n        lm = dspy.LM(model=\"openai/gpt-4o-mini\", cache=False)\n        with dspy.context(send_stream=None, track_usage=False, caller_predict=None):\n            fallback_result = await lm.acall(\"hello\", headers=auth_header)\n\n    fallback_kwargs = fallback_acompletion.call_args.kwargs\n    print(\"fallback_result:\", fallback_result)\n    print(\"fallback_call_kwargs:\", fallback_kwargs)\n\n    assert fallback_result == [\"non-stream\"]\n    assert fallback_kwargs[\"headers\"][\"Authorization\"] == \"Bearer secret-token\"\n    assert fallback_kwargs[\"headers\"][\"User-Agent\"].startswith(\"DSPy/\")\n    assert \"stream_options\" not in fallback_kwargs\n\n\nasyncio.run(main())\n```",
